result.text:
            toast("Proveedor actualizado.");
          } else {
            const res = ensureSupplier(data.name, data.nif);
            if (res.created) {
              updateSupplier(res.supplier.id, {
                phone: data.phone,
                email: data.email,
                note: data.note,
              });
              toast(`Proveedor «${res.supplier.name}» creado.`);
            } else {
              toast("Ese proveedor ya estaba en tu lista.", "bad");
            }
          }
          closeModal();
          render();
        });
      },
    }
  );
}

